def transform(g):
    from collections import Counter
    Hh,Ww=len(g),len(g[0])
    tot=Hh*Ww
    cnt=Counter(x for r in g for x in r)
    common=[c for c,n in cnt.items() if n>tot*0.1]
    def rowfrac(c):
        return max(r.count(c)/Ww for r in g)
    common.sort(key=rowfrac)
    fill,line=common[0],common[-1]
    pts={}; rws=set(); cls=set()
    for r in range(Hh):
        for c in range(Ww):
            v=g[r][c]
            if v not in (fill,line):
                pts[(r,c)]=v; rws.add(r); cls.add(c)
    rs=sorted(rws); cs=sorted(cls)
    M=[[pts.get((r,c),fill) for c in cs] for r in rs]
    out=[]
    for i in range(len(rs)-1):
        row=[]
        for j in range(len(cs)-1):
            b={M[i][j],M[i][j+1],M[i+1][j],M[i+1][j+1]}
            row.append(b.pop() if len(b)==1 else fill)
        out.append(row)
    return out

